export function score(points){return points.reduce((s,p)=>(s[p.winner==='self'?0:1]++,s),[0,0]);}
export function server(points,first='self'){const [a,b]=score(points);const swaps=a>=10&&b>=10?10+(a+b-20):Math.floor((a+b)/2);return swaps%2?(first==='self'?'opponent':'self'):first;}
export function complete(points){const [a,b]=score(points);return Math.max(a,b)>=11&&Math.abs(a-b)>=2;}
export function rate(points){const won=points.filter(p=>p.winner==='self').length;return {won,total:points.length,percent:points.length?Math.round(won/points.length*100):0};}
export function validate(data){if(!data||data.version!==1||!Array.isArray(data.matches)||!Array.isArray(data.opponents))throw Error('备份格式或版本不支持');const ids=new Set();for(const o of data.opponents){if(typeof o.id!=='string'||typeof o.name!=='string'||ids.has(o.id))throw Error('对手数据无效');ids.add(o.id);}const mids=new Set();for(const m of data.matches){if(typeof m.id!=='string'||mids.has(m.id)||!ids.has(m.opponentId)||typeof m.date!=='string'||!Array.isArray(m.games)||!m.games.length)throw Error('比赛数据无效');mids.add(m.id);for(const g of m.games){if(!['self','opponent'].includes(g.first)||!Array.isArray(g.points))throw Error('局数据无效');for(const p of g.points){if(!['self','opponent'].includes(p.winner)||typeof p.id!=='string'||!p.tags||typeof p.tags!=='object'||Array.isArray(p.tags)||Object.values(p.tags).some(v=>typeof v!=='string')||(p.serverOverride&&!['self','opponent'].includes(p.serverOverride)))throw Error('逐分数据无效');}}}return data;}
